create or replace function public.create_booking_hold(p_court_id uuid,p_start_at timestamptz,p_end_at timestamptz,p_total integer,p_hold_minutes integer) returns public.bookings language plpgsql security definer set search_path=public as $$declare b public.bookings;begin if auth.uid() is null then raise exception 'Authentication required';end if;if p_end_at<=p_start_at then raise exception 'Invalid booking range';end if;if exists(select 1 from public.bookings x where x.court_id=p_court_id and x.status in('confirmed','pending_payment') and (x.status='confirmed' or x.hold_expires_at>now()) and tstzrange(x.start_at,x.end_at,'[)')&&tstzrange(p_start_at,p_end_at,'[)')) then raise exception 'SLOT_CONFLICT';end if;if exists(select 1 from public.blocked_times x where (x.court_id=p_court_id or x.court_id is null) and tstzrange(x.start_at,x.end_at,'[)')&&tstzrange(p_start_at,p_end_at,'[)')) then raise exception 'BLOCKED_TIME';end if;insert into public.bookings(booking_reference,user_id,court_id,start_at,end_at,status,total_amount,currency,hold_expires_at)values('GHC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),auth.uid(),p_court_id,p_start_at,p_end_at,'pending_payment',p_total,'PHP',now()+(p_hold_minutes||' minutes')::interval)returning * into b;insert into public.payments(booking_id,amount,currency)values(b.id,b.total_amount,'PHP');return b;end;$$;
revoke all on function public.create_booking_hold(uuid,timestamptz,timestamptz,integer,integer) from public;grant execute on function public.create_booking_hold(uuid,timestamptz,timestamptz,integer,integer) to authenticated;